package com.openminis.app.provider.voice

import org.json.JSONArray
import org.json.JSONObject
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test
import java.io.File
import java.util.Base64

/**
 * [FIX-261022-06, OpenMinis#468 / #469] The Bailian, iFlytek and Doubao ASR
 * wire formats, checked against src/shared/voice-asr/cloud_asr_vectors.json -
 * the vectors iOS and Windows run too, generated by an independent Python
 * reference (gen_vectors.py). The vendors' acceptance of these requests is
 * from their docs, not verified with a real key.
 */
class CloudAsrProtocolsTest {

    private val vectors: JSONObject by lazy {
        val file = listOf(
            File("../../shared/voice-asr/cloud_asr_vectors.json"), // CWD = src/android/app
            File("../shared/voice-asr/cloud_asr_vectors.json"),    // CWD = src/android
        ).first { it.exists() }
        JSONObject(file.readText())
    }

    private fun b64(s: String): ByteArray = Base64.getDecoder().decode(s)

    /** JSON equality that ignores key order. */
    private fun assertJson(expected: Any?, actual: Any?, path: String = "$") {
        when (expected) {
            is JSONObject -> {
                actual as? JSONObject ?: fail("$path: expected an object, got $actual")
                actual as JSONObject
                assertEquals("$path keys", expected.keySet(), actual.keySet())
                for (k in expected.keySet()) assertJson(expected.get(k), actual.get(k), "$path.$k")
            }
            is JSONArray -> {
                actual as? JSONArray ?: fail("$path: expected an array, got $actual")
                actual as JSONArray
                assertEquals("$path length", expected.length(), actual.length())
                for (i in 0 until expected.length()) assertJson(expected.get(i), actual.get(i), "$path[$i]")
            }
            is Number -> assertEquals(path, expected.toDouble(), (actual as Number).toDouble(), 0.0)
            else -> assertEquals(path, expected, actual)
        }
    }

    @Test
    fun `any PCM WAV becomes 16 kHz mono 16-bit PCM`() {
        val cases = vectors.getJSONArray("pcm16k")
        for (i in 0 until cases.length()) {
            val c = cases.getJSONObject(i)
            val got = CloudAsrProtocols.pcm16kMono(b64(c.getString("wav")))
            if (c.isNull("pcm")) {
                assertNull(c.getString("name"), got)
            } else {
                assertArrayEquals(c.getString("name"), b64(c.getString("pcm")), got)
            }
        }
    }

    @Test
    fun `44_1 kHz is resampled to the 16 kHz length`() {
        val frames = 4410
        val pcm = java.nio.ByteBuffer.allocate(frames * 2).order(java.nio.ByteOrder.LITTLE_ENDIAN)
        repeat(frames) { pcm.putShort((it % 100).toShort()) }
        val wav = VoiceProvider.wrapPcm16InWav(pcm.array(), 44_100)
        assertEquals(1600 * 2, CloudAsrProtocols.pcm16kMono(wav)!!.size)
    }

    @Test
    fun `iFlytek frames, language and segments`() {
        val f = vectors.getJSONObject("xunfei_frames")
        val got = CloudAsrProtocols.xunfeiFrames(b64(f.getString("pcm")), f.getString("app_id"), f.getString("language"))
        assertJson(f.getJSONArray("frames"), JSONArray(got.map { JSONObject(it) }))

        val langs = vectors.getJSONArray("xunfei_language")
        for (i in 0 until langs.length()) {
            val pair = langs.getJSONArray(i)
            val tag = if (pair.isNull(0)) null else pair.getString(0)
            assertEquals(tag.toString(), pair.getString(1), CloudAsrProtocols.xunfeiLanguage(tag))
        }

        val seg = vectors.getJSONObject("xunfei_segments")
        val sizes = CloudAsrProtocols.xunfeiSegments(ByteArray(seg.getInt("pcm_bytes"))).map { it.size }
        val expected = seg.getJSONArray("segment_bytes").let { a -> (0 until a.length()).map { a.getInt(it) } }
        assertEquals(expected, sizes)
    }

    @Test
    fun `iFlytek results are joined in order, rpl replaces, an error code throws`() {
        val cases = vectors.getJSONArray("xunfei_results")
        for (i in 0 until cases.length()) {
            val c = cases.getJSONObject(i)
            val result = CloudAsrProtocols.XunfeiResult()
            val messages = c.getJSONArray("messages")
            if (c.has("error_code")) {
                try {
                    for (k in 0 until messages.length()) result.accept(messages.getString(k))
                    fail("case $i: expected an error")
                } catch (e: CloudAsrProtocols.XunfeiResult.Failure) {
                    assertEquals(c.getInt("error_code"), e.code)
                }
                continue
            }
            var last = false
            for (k in 0 until messages.length()) last = result.accept(messages.getString(k))
            assertTrue("case $i ends on status 2", last)
            assertEquals("case $i", c.getString("text"), result.text)
        }
    }

    @Test
    fun `Bailian model, body and response`() {
        val models = vectors.getJSONArray("bailian_model")
        for (i in 0 until models.length()) {
            val pair = models.getJSONArray(i)
            val id = if (pair.isNull(0)) null else pair.getString(0)
            assertEquals(id.toString(), pair.getString(1), CloudAsrProtocols.bailianModel(id))
        }
        val bodies = vectors.getJSONArray("bailian_body")
        for (i in 0 until bodies.length()) {
            val c = bodies.getJSONObject(i)
            val lang = if (c.isNull("language")) null else c.getString("language")
            assertJson(
                c.getJSONObject("body"),
                CloudAsrProtocols.bailianBody(c.getString("model"), b64(c.getString("wav")), lang),
            )
        }
        val r = vectors.getJSONObject("bailian_response")
        val (text, seconds) = CloudAsrProtocols.bailianParse(r.getString("body"))!!
        assertEquals(r.getString("text"), text)
        assertEquals(r.getDouble("seconds"), seconds!!, 0.0)
        assertNull(CloudAsrProtocols.bailianParse("{\"error\":{\"message\":\"x\"}}"))
    }

    @Test
    fun `Doubao resource and body`() {
        val res = vectors.getJSONArray("doubao_resource")
        for (i in 0 until res.length()) {
            val pair = res.getJSONArray(i)
            val id = if (pair.isNull(0)) null else pair.getString(0)
            assertEquals(id.toString(), pair.getString(1), CloudAsrProtocols.doubaoResource(id))
        }
        val b = vectors.getJSONObject("doubao_body")
        assertJson(b.getJSONObject("body"), CloudAsrProtocols.doubaoBody(b64(b.getString("wav"))))
    }

    @Test
    fun `Doubao failures say what to do`() {
        val grant = CloudAsrProtocols.doubaoFailure("45000030", "requested resource not granted", 403, "volc.bigasr.auc_turbo")
        assertTrue(grant, grant.contains("45000030") && grant.contains("volc.bigasr.auc_turbo"))
        val key = CloudAsrProtocols.doubaoFailure("45000010", "Invalid X-Api-Key", 401, "volc.bigasr.auc_turbo")
        assertTrue(key, key.contains("API Key"))
        assertEquals("Doubao ASR failed (HTTP 500)", CloudAsrProtocols.doubaoFailure(null, null, 500, "r"))
    }
}
